import React, { useState } from 'react';
import { ResizableBox } from 'react-resizable';
import Draggable from 'react-draggable';
import 'react-resizable/css/styles.css';

const DraggableResizable = ({ children, defaultWidth, defaultHeight, defaultX, defaultY, onResizeStop, onDragStop }) => {
  const [isResizing, setIsResizing] = useState(false);

  const handleResizeStart = () => {
    setIsResizing(true);
  };

  const handleResizeStop = (e, data) => {
    setIsResizing(false);
    onResizeStop(data);
  };

  const handleDragStop = (e, data) => {
    onDragStop(data);
  };

  return (
    <Draggable
      handle=".drag-handle"
      onStop={handleDragStop}
      defaultPosition={{ x: defaultX, y: defaultY }}
      bounds="parent"
    >
      <div>
        <ResizableBox
          width={defaultWidth}
          height={defaultHeight}
          minConstraints={[100, 100]}
          maxConstraints={[800, 800]}
          onResizeStart={handleResizeStart}
          onResizeStop={handleResizeStop}
          resizeHandles={['n', 'e', 's', 'w', 'nw', 'ne', 'sw']}
        >
          <div style={{ position: 'relative', width: '100%', height: '100%' }}>
            {children}
            <div className="drag-handle" style={{ width: 20, height: 20, backgroundColor: '#6441a4', position: 'absolute', bottom: 0, right: 0, cursor: 'move' }} />
          </div>
        </ResizableBox>
      </div>
    </Draggable>
  );
};

export default DraggableResizable;
